alter table public.gestores add column telefono text;
create table public.customer_bindings (
 phone text primary key,agent_name text not null,
 created_at timestamptz default now(),updated_at timestamptz default now(),
 last_followup_at timestamptz,followup_expires_at timestamptz,
 followup_closed_at timestamptz,followup_close_reason text
 ,protected_until timestamptz,last_activity_at timestamptz,last_activity_type text,
 last_purchase_at timestamptz,last_order_id text,previous_agent_name text,transferred_at timestamptz
);
create table public.customer_binding_events (
 id bigint generated by default as identity primary key,
 phone text,agent_name text,previous_agent_name text,event_type text,
 order_id text,occurred_at timestamptz default now(),metadata jsonb,protected_until timestamptz
);
grant select,insert,update,delete on public.customer_bindings,public.customer_binding_events to service_role;
grant usage on all sequences in schema public to service_role;
